print value = coalesce(tostring(Accounts[0]), tostring(Accounts[0]))"},{"id":"11395ab3-1314-5e4f-a429-820d8d3b9c37","version":"KqlParameterItem/1.0","name":"AccountJson1","type":1,"isHiddenWhenLocked":true,"queryType":12,"query":"{"version":"ARMEndpoint/1.0","data":null,"headers":[],"method":"GET","path":"{FoundryAccount1}","urlParams":[{"key":"api-version","value":"2024-10-01"}],"transformers":[{"type":"jsonpath","settings":{"tablePath":"$","columns":[{"path":"$","columnid":"value"}]}}]}"},{"id":"8c12a67f-e875-5aba-8820-1394ee0bfb49","version":"KqlParameterItem/1.0","name":"DeploymentJson1","type":1,"isHiddenWhenLocked":true,"queryType":12,"query":"{"version":"ARMEndpoint/1.0","data":null,"headers":[],"method":"GET","path":"{FoundryAccount1}/deployments","urlParams":[{"key":"api-version","value":"2024-10-01"}],"transformers":[{"type":"jsonpath","settings":{"tablePath":"$","columns":[{"path":"$","columnid":"value"}]}}]}"},{"id":"a75ae917-5deb-5b45-9938-f75ed10d1282","version":"KqlParameterItem/1.0","name":"SourceJson1","type":1,"isHiddenWhenLocked":true,"queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["{Workspace}"],"query":"let Account = parse_json(base64_decode_tostring('{AccountJson1:base64}'));
let Inventory = parse_json(base64_decode_tostring('{DeploymentJson1:base64}'));
let SelectedAccountCount = array_length(split(strcat_array(dynamic([{Foundry}]), ','), ','));
let Domain = tolower(tostring(Account.properties.customSubDomainName));
let Endpoints = toscalar(print Entries = Account.properties.endpoints
    | mv-expand kind=array Entry = Entries
    | extend Host = tolower(tostring(parse_url(tostring(Entry[1])).Host))
    | where isnotempty(Domain) and Host startswith strcat(Domain, '.')
    | summarize make_bag(bag_pack(Host, strcat('https://', Host))));
let Items = toscalar(print Entry = Inventory.value
    | mv-expand Entry
    | where tostring(Entry.sku.name) contains 'Provisioned'
    | project Item = bag_pack('name', Entry.name,
        'sku', bag_pack('name', Entry.sku.name, 'capacity', Entry.sku.capacity),
        'properties', bag_pack('currentCapacity', Entry.properties.currentCapacity,
            'provisioningState', Entry.properties.provisioningState),
        'systemData', bag_pack('createdAt', Entry.systemData.createdAt,
            'lastModifiedAt', Entry.systemData.lastModifiedAt))
    | summarize make_list(Item));
let CompactInventory = iff(gettype(Inventory) == 'dictionary' and gettype(Inventory.value) == 'array',
    bag_pack('value', Items, 'nextLink', Inventory.nextLink), Inventory);
let CompactAccount = bag_pack('id', Account.id, 'properties', bag_pack(
    'endpoint', Account.properties.endpoint, 'customSubDomainName', Account.properties.customSubDomainName,
    'endpoints', Endpoints));
print value = iff(SelectedAccountCount >= 1,
    tostring(bag_pack('account', CompactAccount, 'inventory', CompactInventory)), '{}')
